parameters.jsCode:
// Extract and normalize booking parameters from Cal.com webhook
const payload = $input.first().json.body || $input.first().json;
const booking = payload.payload || payload.data || payload;
const attendee = booking.attendees?.[0] || {};

const rawPhone = attendee.phoneNumber || attendee.phone || booking.responses?.phone?.value || booking.responses?.phone || '';
let phone = rawPhone.replace(/[^\d+]/g, '');
if (phone.length === 10 && !phone.startsWith('+')) {
  phone = `+91${phone}`;
}

const email = (attendee.email || booking.responses?.email?.value || booking.responses?.email || '').toLowerCase().trim();
const name = attendee.name || booking.responses?.name?.value || booking.responses?.name || 'Valued Client';
const startTime = booking.startTime || booking.start_time || new Date().toISOString();
const timezone = attendee.timeZone || booking.timezone || 'Asia/Kolkata';
const meetingLink = booking.videoCallData?.url || booking.location || booking.meetingUrl || '';
const bookingUid = String(booking.uid || booking.bookingId || booking.id || `bk-${Date.now()}`);
const notes = booking.responses?.problem?.value || booking.responses?.problem || booking.description || 'Discovery Call';

const formattedDate = new Date(startTime).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const formattedTime = new Date(startTime).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

return [{
  json: {
    bookingUid,
    name,
    email,
    phone,
    startTime,
    timezone,
    meetingLink,
    formattedDate,
    formattedTime,
    meetingDateTimeStr: `${formattedDate} at ${formattedTime} (${timezone})`,
    notes
  }
}];

